cypress_script:
describe('User Avatars Profile Links', () => {
  it('should reveal profile link on hover for the first user', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').first().trigger('mouseover');
    cy.contains('View profile').should('be.visible');
    cy.get('div.figure').first().find('a').should('have.attr', 'href', '/users/1');
  });

  it('should not navigate away when hovering', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').first().trigger('mouseover');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars Profile Links', () => {
  test('should reveal profile link on hover for the first user', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('div.figure');
    await expect(page.locator('text=View profile')).toBeVisible();
    const link = await page.locator('div.figure a').first().getAttribute('href');
    expect(link).toBe('/users/1');
  });

  test('should not navigate away when hovering', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('div.figure');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/hovers');
  });
});
